            prediction_type=v818.RewindType.VEHICLE,
            pos=v818.Vec3(x=1.0, y=2.0, z=3.0),
            pos_delta=v818.Vec3(x=0.0, y=0.5, z=0.0),
            vehicle_rotation=v818.Vec2(x=0.25, y=0.75),
            vehicle_angular_velocity=1.5,
            on_ground=True,
            tick=300,
