@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_correct_player_move_prediction_is_packet_161(version):
    assert version.PACKETS[161] is version.CorrectPlayerMovePredictionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_correct_player_move_prediction_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_correct_player_move_prediction_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_pre_827_prediction_leaves_the_vehicle_fields_off_the_wire_for_a_player():
    packet = v818.CorrectPlayerMovePredictionPacket(
        prediction_type=v818.RewindType.PLAYER,
        pos=v818.Vec3(x=1.0, y=2.0, z=3.0),
        pos_delta=v818.Vec3(x=0.0, y=0.5, z=0.0),
        vehicle_rotation=v818.Vec2(x=9.0, y=9.0),
        on_ground=True,
        tick=300,
    )
    assert bytes(packet) == V818_PLAYER


def test_827_is_a_distinct_prediction_from_818():
    assert v818.CorrectPlayerMovePredictionPacket is not v827.CorrectPlayerMovePredictionPacket
